// Des: Doctor: check that each job's first button or box exists on its page (read-only)
// Flo: browser version check > for each job (or one) visit its page > find the first labeled step by role + label > OK or MISSING > count
// I/O: Ctx + optional job name + optional --url path (caller) > lines on stdout, count of OK; error Drift when anything is missing
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const pack = @import("ut-loca-pack.zig");
fn roleOf(tpl: jobs.T) []const u8 { if (tpl.role.len > 0) return tpl.role; return switch (tpl.op) { .typez, .clear => "textbox", .toggle => "checkbox", else => "button" }; }
fn firstLabeled(job: *const jobs.Job) ?jobs.T { for (job.steps) |tpl| { if (tpl.key.len > 0 and tpl.op != .expect and tpl.op != .toggle) return tpl; } return null; }
fn check(ctx: *task.Ctx, name: []const u8, path: []const u8, key: []const u8, role: []const u8, miss: *u32, okay: *u32) !void { try task.visit(ctx, path); ctx.page.arm(ctx.conf.brow_time_seco * 1000); const labs = pack.lab(ctx.conf, key); const found = (try ctx.page.axFind(ctx.aren, role, labs, 0)) != null; if (found) { okay.* += 1; task.say(ctx, "OK      {s}: {s} ({s})", .{ name, key, role }); } else { miss.* += 1; task.say(ctx, "MISSING {s}: {s} ({s}) on {s}", .{ name, key, role, path }); } }
fn chromeMajor(ctx: *task.Ctx) u32 { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const res = ctx.page.call(ctx.aren, "Browser.getVersion", "") catch return 0; if (res != .object) return 0; const pro = res.object.get("product") orelse return 0; if (pro != .string) return 0; const at = std.mem.findScalar(u8, pro.string, '/') orelse return 0; var end = at + 1; while (end < pro.string.len and pro.string[end] >= '0' and pro.string[end] <= '9') end += 1; return std.fmt.parseInt(u32, pro.string[at + 1 .. end], 10) catch 0; }
pub fn doctor(ctx: *task.Ctx, only: []const u8, urlz: []const u8) !u32 { var miss: u32 = 0; var okay: u32 = 0; const maj = chromeMajor(ctx); if (maj > 0) { if (maj < ctx.conf.brow_vers_minz) { miss += 1; task.say(ctx, "MISSING browser: Chrome {d} is older than brow_vers_minz {d}", .{ maj, ctx.conf.brow_vers_minz }); } else task.say(ctx, "OK      browser: Chrome {d}", .{maj}); } for (&jobs.JOBS) |*jb| { if (only.len > 0 and !std.mem.eql(u8, jb.name, only)) continue; const tpl = firstLabeled(jb) orelse continue; if (jb.path.len == 0 and urlz.len == 0) continue; const path = try jrun.pathOf(ctx, jb, .{ .url = urlz }); try check(ctx, jb.name, path, tpl.key, roleOf(tpl), &miss, &okay); } task.say(ctx, "doctor: {d} ok, {d} missing", .{ okay, miss }); if (miss > 0) return error.Drift; return okay; }
